# Let's try to find minimal edit operations
def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that converts s_in to s_out"""
    # Simple approach: find first difference and try to match patterns

    # If lengths are equal, look for character substitution
    if len(s_in) == len(s_out):
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
    # If output is longer, look for insertion
    elif len(s_out) > len(s_in):
        # Find where the extra character appears
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                # Insertion happened at position i
                return (s_in[i], s_out[i], i)
        # Extra character at end
        return (s_in[-1], s_out[-1], len(s_in)-1)
    # If output is shorter, look for deletion
    else:
        # Find where characters don't match
        for i in range(len(s_out)):
            if s_in[i] != s_out[i]:
                return (s_in[i], s_out[i], i)
        # Deletion at end
        return (s_in[len(s_out)], '', len(s_out))

    return None

